// Security headers, in one place.
//
// - The UI (index.html, /assets/*, sw.js, the manifest, icons) is served by Workers static assets,
//   which never runs the Worker, so its headers (and its caching rules) live in dist/_headers: vite.config.ts writes that file
//   with headersFile() after each build, hashing the inline <script>s it finds in dist/index.html.
//   https://developers.cloudflare.com/workers/static-assets/headers/
// - Responses the Worker builds (/api, /agent/api, /hooks) get API_HEADERS from worker/http.ts json();
//   _headers is "not applied to responses generated by your Worker code".
//
// Tested in test/shared/security-headers.test.ts and test/worker/headers.test.ts; the e2e suite
// (e2e/security.spec.ts) checks the live headers and that the pages raise no CSP violations.

const COMMON: Record<string, string> = {
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "same-origin",
  // .dev is HSTS-preloaded already; this covers a custom domain. No includeSubDomains: not our zone.
  "Strict-Transport-Security": "max-age=31536000",
};

// JSON never renders as a page, so its policy allows nothing.
export const API_HEADERS: Record<string, string> = {
  "Content-Type": "application/json",
  "Cache-Control": "no-store",
  ...COMMON,
  "Content-Security-Policy": "default-src 'none'; frame-ancestors 'none'; base-uri 'none'",
};

// Only features Chrome recognizes: an unknown name logs a console error on every load.
const PERMISSIONS_POLICY = [
  "accelerometer", "camera", "display-capture", "geolocation", "gyroscope", "magnetometer", "microphone", "payment", "usb",
].map((f) => f + "=()").join(", ");

export const APP_HEADERS: Record<string, string> = {
  ...COMMON,
  "Permissions-Policy": PERMISSIONS_POLICY,
  "Cross-Origin-Opener-Policy": "same-origin",
};

// The UI's policy. Everything is same-origin (fonts are bundled, not Google Fonts); the one inline
// script (index.html's theme, run before first paint) is allowed by hash; data: images are the
// inline SVG favicon. No 'unsafe-inline' anywhere: views use classes, never style attributes.
export function appCsp(scriptHashes: string[]): string {
  return [
    "default-src 'self'",
    ["script-src 'self'", ...scriptHashes].join(" "),
    "style-src 'self'",
    "img-src 'self' data:",
    "font-src 'self'",
    "connect-src 'self'",
    "manifest-src 'self'",
    "worker-src 'self'",
    "frame-ancestors 'none'",
    "base-uri 'none'",
    "form-action 'self'",
    "object-src 'none'",
  ].join("; ");
}

// Caching, on top of the static-assets default ("public, max-age=0, must-revalidate", which / and
// index.html keep): Vite's /assets/ names carry a content hash, so a name never changes content and
// browsers can keep it for a year without asking; sw.js is revalidated on every update check, so a
// deploy reaches installed apps promptly. A request matching several rules gets all their headers, and
// one header set by two rules is joined with a comma, so /* sets no Cache-Control of its own.
// https://developers.cloudflare.com/workers/static-assets/headers/
export const CACHE_RULES: Record<string, Record<string, string>> = {
  "/assets/*": { "Cache-Control": "public, max-age=31536000, immutable" },
  "/sw.js": { "Cache-Control": "no-cache" },
};

export function headersFile(scriptHashes: string[]): string {
  const rules = { "/*": { "Content-Security-Policy": appCsp(scriptHashes), ...APP_HEADERS }, ...CACHE_RULES };
  return (
    "# Generated by vite.config.ts from shared/security-headers.ts; edit that, not this.\n" +
    Object.entries(rules)
      .map(([path, headers]) => path + "\n" + Object.entries(headers).map(([k, v]) => `  ${k}: ${v}\n`).join(""))
      .join("")
  );
}

// The CSP source expression for an inline script's exact text.
export async function scriptHash(body: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(body));
  let bin = "";
  for (const b of new Uint8Array(digest)) bin += String.fromCharCode(b);
  return "'sha256-" + btoa(bin) + "'";
}

// Bodies of the <script> elements without a src, verbatim (the hash covers every byte).
export function inlineScripts(html: string): string[] {
  return [...html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)].filter((m) => !/\ssrc\s*=/i.test(m[1])).map((m) => m[2]);
}

// What in this markup (a page, or a view's HTML strings) the policy above would block.
export function htmlCspProblems(html: string): string[] {
  const out: string[] = [];
  for (const m of html.matchAll(/\sstyle\s*=/gi)) out.push("style attribute at " + m.index);
  for (const m of html.matchAll(/\son[a-z]+\s*=\s*["']/gi)) out.push("inline event handler at " + m.index);
  for (const m of html.matchAll(/javascript:/gi)) out.push("javascript: URL at " + m.index);
  for (const m of html.matchAll(/<(?:script|link)\b[^>]*\s(?:src|href)\s*=\s*["']?(?:https?:)?\/\//gi)) out.push("third-party resource at " + m.index);
  return out;
}
